import React, { useEffect, useMemo, useRef, useState } from "react";
import { Link, useLocation, useNavigate, useParams } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { MapPin, ArrowLeft, Calendar, CheckCircle2, Clock } from "lucide-react";
import { API_URL } from "../config";
import AccountabilityChain from "./AccountabilityChain";
import {
  buildMapReturnUrl,
  getIssuePath,
  loadMapState,
  resolveComplaintId,
} from "../utils/issueNavigation";

function IssuePage() {
  const { slug } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const cardRef = useRef(null);
  const [complaints, setComplaints] = useState([]);
  const [loading, setLoading] = useState(true);
  const fromMap = location.state?.fromMap;

  useEffect(() => {
    fetch(`${API_URL}/public-complaints`)
      .then((r) => r.json())
      .then((data) => {
        setComplaints(data);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const issueId = useMemo(
    () => resolveComplaintId(slug, complaints),
    [slug, complaints]
  );

  const complaint = useMemo(
    () => complaints.find((c) => c._id === issueId),
    [complaints, issueId]
  );

  useEffect(() => {
    if (!loading && complaint && cardRef.current) {
      const t = setTimeout(() => {
        cardRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
      }, 350);
      return () => clearTimeout(t);
    }
  }, [loading, complaint]);

  const mapReturn = buildMapReturnUrl(loadMapState());
  const isResolved = complaint?.status === "Resolved";

  return (
    <motion.div
      className="min-h-screen bg-[#0a0a0a] text-white"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.35, ease: [0.25, 0.1, 0.25, 1] }}
    >
      <div className="absolute inset-0 bg-gradient-to-br from-indigo-950/40 via-[#0a0a0a] to-violet-950/30 pointer-events-none" />

      <div className="relative z-10 container mx-auto px-4 py-24 max-w-3xl">
        <Link
          to={mapReturn}
          className="inline-flex items-center gap-2 text-sm text-indigo-300 hover:text-white mb-8 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to live map
        </Link>

        <AnimatePresence mode="wait">
          {loading ? (
            <div className="flex justify-center py-24">
              <div className="h-12 w-12 rounded-full border-4 border-indigo-500/30 border-t-indigo-400 animate-spin" />
            </div>
          ) : !complaint ? (
            <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 p-8 text-center">
              <p className="text-amber-200 font-medium">Issue not found</p>
              <Link to="/track-status" className="text-indigo-300 underline mt-4 inline-block">
                Browse all issues
              </Link>
            </div>
          ) : (
            <motion.div
              key={complaint._id}
              layoutId={fromMap ? `issue-card-${complaint._id}` : undefined}
              ref={cardRef}
              initial={fromMap ? { scale: 0.96, opacity: 0 } : { opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              transition={{ duration: 0.45, ease: [0.25, 0.1, 0.25, 1] }}
              className="complaint-highlight-card rounded-3xl border-2 border-indigo-400/80 bg-[#12121a]/90 backdrop-blur-xl shadow-[0_0_60px_rgba(99,102,241,0.25)] overflow-hidden"
            >
              {fromMap && (
                <motion.div
                  initial={{ opacity: 0, y: -8 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-indigo-600/90 px-5 py-3 text-center text-sm font-semibold tracking-wide"
                >
                  Viewing selected issue from map
                </motion.div>
              )}

              <div className="p-8">
                <motion.div
                  className="flex flex-wrap items-start justify-between gap-4 mb-6"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: 0.1 }}
                >
                  <div>
                    <span className="inline-block px-3 py-1 rounded-full bg-indigo-500/20 text-indigo-200 text-xs font-bold uppercase mb-2">
                      {complaint.category}
                    </span>
                    <h1 className="text-2xl md:text-3xl font-extrabold text-white">
                      Civic issue report
                    </h1>
                    <p className="text-xs font-mono text-gray-500 mt-1">{complaint._id}</p>
                  </div>
                  {isResolved ? (
                    <span className="flex items-center gap-1.5 bg-emerald-500/20 text-emerald-300 px-4 py-2 rounded-full text-sm font-bold">
                      <CheckCircle2 className="w-4 h-4" /> Resolved
                    </span>
                  ) : (
                    <span className="flex items-center gap-1.5 bg-amber-500/20 text-amber-200 px-4 py-2 rounded-full text-sm font-bold">
                      <Clock className="w-4 h-4" /> {complaint.status}
                    </span>
                  )}
                </motion.div>

                <div className="space-y-4 mb-8">
                  <div className="flex items-start gap-3 text-gray-300">
                    <MapPin className="w-5 h-5 text-indigo-400 shrink-0 mt-0.5" />
                    <p>{complaint.location}</p>
                  </div>
                  <p className="text-gray-400 leading-relaxed">"{complaint.description}"</p>
                  <div className="flex items-center gap-2 text-sm text-gray-500">
                    <Calendar className="w-4 h-4" />
                    Reported{" "}
                    {complaint.date
                      ? new Date(complaint.date).toLocaleDateString("en-IN", {
                          day: "numeric",
                          month: "short",
                          year: "numeric",
                        })
                      : "N/A"}
                  </div>
                </div>

                {complaint.latitude && complaint.longitude && (
                  <motion.div
                    className="mb-8 rounded-2xl overflow-hidden border border-white/10 h-48 bg-[#0a0a0a]"
                    initial={{ opacity: 0, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.2 }}
                  >
                    <iframe
                      title="Issue location"
                      className="w-full h-full border-0 grayscale-[30%] contrast-110"
                      loading="lazy"
                      src={`https://www.openstreetmap.org/export/embed.html?bbox=${complaint.longitude - 0.01}%2C${complaint.latitude - 0.01}%2C${complaint.longitude + 0.01}%2C${complaint.latitude + 0.01}&layer=mapnik&marker=${complaint.latitude}%2C${complaint.longitude}`}
                    />
                  </motion.div>
                )}

                <AccountabilityChain
                  complaintId={complaint._id}
                  lat={complaint.latitude}
                  lng={complaint.longitude}
                  issueType={complaint.category}
                  location={complaint.location}
                />

                <motion.div className="mt-8 flex flex-wrap gap-3">
                  <Link
                    to={mapReturn}
                    className="px-5 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-semibold text-sm transition"
                  >
                    View on map
                  </Link>
                  <Link
                    to="/track-status"
                    className="px-5 py-2.5 rounded-xl border border-white/20 hover:bg-white/10 text-sm font-semibold transition"
                  >
                    All public issues
                  </Link>
                  <button
                    type="button"
                    onClick={() => navigate(getIssuePath(complaint), { replace: true })}
                    className="px-5 py-2.5 rounded-xl border border-white/10 text-gray-400 text-sm"
                  >
                    Copy link
                  </button>
                </motion.div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

export default IssuePage;
